from pathlib import Path
import base64

root = Path(__file__).resolve().parents[1]
out = root / '.impeccable/mocks/decision'
out.mkdir(parents=True, exist_ok=True)
photo = 'data:image/jpeg;base64,' + base64.b64encode((root / 'public/images/courts-panorama.jpg').read_bytes()).decode()
font = 'data:font/ttf;base64,' + base64.b64encode((root / 'public/fonts/bricolage-grotesque.ttf').read_bytes()).decode()
common = '''*{box-sizing:border-box}body{margin:0;width:1440px;height:900px;overflow:hidden;background:#f4f5eb;color:#16392e;font-family:Bricolage,sans-serif}header{height:100px;padding:0 64px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:32px;font-weight:800}.brand small{display:inline-block;font-size:12px;width:80px;line-height:1.3;margin-left:12px;font-weight:600}.nav{font-size:16px;display:flex;gap:36px;align-items:center}.button{padding:17px 26px;background:#d8f36a;color:#15392e;display:inline-block;border-radius:5px;font-size:17px;font-weight:700}h1{font-size:96px;line-height:.98;font-weight:700;letter-spacing:-.04em;margin:0}p{font-size:20px;line-height:1.6}.strip{display:flex;align-items:center;gap:36px;padding:22px 30px;background:#f4f5eb;color:#15392e}.strip>div{flex:1}.strip strong{display:block;font-size:16px}.strip span{display:block;font-size:14px;margin-top:8px}.strip .button{flex:0 0 200px;text-align:center}'''
head = '<header><div class="brand">ATB<small>ABOUT THE BEST<br>TENNIS ACADEMY</small></div><div class="nav">The academy &nbsp; Coaching &nbsp; Our champions &nbsp; <span class="button">Find your court time ↗</span></div></header>'
strip = '<div class="strip"><div><strong>I want to</strong><span>Book a court</span></div><div><strong>Preferred day</strong><span>Choose a date</span></div><div><strong>Preferred time</strong><span>Choose a time</span></div><div class="button">Plan your session ↗</div></div>'
worlds = {
'courtside': ('header{background:#15392e;color:#f4f5eb}main{margin:18px;border-radius:12px;height:726px;background:linear-gradient(90deg,rgba(11,35,26,.75),rgba(11,35,26,.08)),url("'+photo+'");background-size:cover;background-position:center;position:relative;padding:68px 56px;color:#fff}h1 span{color:#d8f36a}main p{max-width:480px;color:#eef1e4}main .strip{position:absolute;left:40px;right:40px;bottom:32px;border-radius:10px}.loc{margin-top:28px;font-size:14px;letter-spacing:.08em}.below{padding:6px 64px;font-size:26px}', '<main><h1>Good things<br>start with<br><span>a first serve.</span></h1><p>Coaching. Competition. A court to call your own.<br>Find your game at ATB, Yelahanka.</p><div class="loc">OUTDOOR CLAY COURTS · YELAHANKA, BENGALURU</div>'+strip+'</main><div class="below">A little fresh air. A lot of possibility.</div>'),
'club': ('header{border-bottom:1px solid #ccd1c5}.intro{padding:42px 64px;display:flex;justify-content:space-between;align-items:end}h1{font-size:90px}.intro p{max-width:340px}.scene{margin:0 40px;height:410px;border-radius:12px;background:url("'+photo+'");background-size:cover;background-position:center 57%;position:relative}.scene .strip{position:absolute;bottom:-60px;left:40px;right:40px;border-radius:12px;background:#15392e;color:#f4f5eb}.scene .button{color:#15392e}.foot{padding:90px 80px 0;font-size:25px}', '<section class="intro"><h1>Your neighbourhood.<br>Your <span style="color:#648349">centre court.</span></h1><p>A space to learn, play and keep coming back.<br><br>Welcome to ATB Tennis Academy.</p></section><div class="scene">'+strip+'</div><div class="foot">For the first-timers. The early risers. The match-point chasers.</div>'),
'canon': ('.hero{padding:60px 64px;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.hero img{width:100%;height:450px;object-fit:cover;border-radius:12px}h1{font-size:76px}.cards{display:flex;gap:30px;margin:25px 64px}.cards article{background:#e7edda;padding:35px;flex:1;border-radius:12px;font-size:24px}', '<section class="hero"><div><h1>Find your game<br>at ATB.</h1><p>Tennis coaching and outdoor clay courts<br>in Yelahanka, Bengaluru.</p><span class="button">Book a court ↗</span></div><img src="'+photo+'" alt="ATB clay courts"></section><section class="cards"><article>Junior coaching</article><article>Adult coaching</article><article>Competitive tennis</article></section>')
}
for name, (css, content) in worlds.items():
    html = '<!doctype html><html lang="en"><meta charset="utf-8"><title>ATB — '+name+'</title><style>@font-face{font-family:Bricolage;src:url("'+font+'")}'+common+css+'</style>'+head+content+'</html>'
    (out / (name+'.html')).write_text(html, encoding='utf-8')
print('Wrote three first-viewport design previews.')
